/// <reference types="vite/client" />

// Vite stelt afbeeldingen beschikbaar als URL-imports.
declare module '*.png' {
  const src: string;
  export default src;
}
declare module '*.jpg' {
  const src: string;
  export default src;
}
declare module '*.svg' {
  const src: string;
  export default src;
}
